// ===== Express BFF：手动聚合多个微服务 =====
const express = require('express');
const app = express();

app.get('/api/dashboard', async (req, res) => {
  try {
    // 服务端并行调三个微服务，一次返回
    const [userRes, ordersRes, notifRes] = await Promise.all([
      fetch(`http://user-service/api/users/${req.userId}`),
      fetch(`http://order-service/api/orders?userId=${req.userId}&limit=10`),
      fetch(`http://notification-service/api/notifications?userId=${req.userId}&unread=true`)
    ]);

    const user = await userRes.json();
    const orders = await ordersRes.json();
    const notifications = await notifRes.json();

    // 裁剪：只返回移动端需要的字段
    res.json({
      userName: user.name,
      avatar: user.avatar,
      recentOrders: orders.map(o => ({ id: o.id, title: o.title, amount: o.amount })),
      unreadCount: notifications.length
    });
  } catch (err) {
    // 降级：部分服务失败时返回可用数据
    res.status(200).json({ error: 'partial data unavailable' });
  }
});

// ===== GraphQL BFF：前端自声明字段 =====
const { ApolloServer, gql } = require('apollo-server');

const typeDefs = gql`
  type User { id: ID!, name: String!, avatar: String, orders: [Order!]! }
  type Order { id: ID!, title: String!, amount: Float! }
  type Query { dashboard: Dashboard! }
  type Dashboard { userName: String!, avatar: String, recentOrders: [Order!]!, unreadCount: Int! }
`;

const resolvers = {
  Query: {
    dashboard: async (_, __, { userId }) => {
      // DataLoader 批量加载防 N+1
      const [user, orders, notifications] = await Promise.all([
        fetchUser(userId),
        fetchOrdersByUser(userId, { limit: 10 }),
        fetchUnreadNotifications(userId)
      ]);
      return {
        userName: user.name,
        avatar: user.avatar,
        recentOrders: orders,
        unreadCount: notifications.length
      };
    }
  }
};

